export const BizAdminView = ({ section, userRole }: { section?: string, userRole: UserRole }) => {
  const [users, setUsers] = useState<DBUser[]>([]);
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [selectedPolicy, setSelectedPolicy] = useState<Policy | null>(null);
  const [policyTransactions, setPolicyTransactions] = useState<Transaction[]>([]);
  const [isAddingUser, setIsAddingUser] = useState(false);
  const [loading, setLoading] = useState(false);

  const [userForm, setUserForm] = useState({
    name: '', email: '', phone: '', password: '', role: UserRole.CUSTOMER
  });

  const fetchData = async () => {
      const allUsers = await db.users.toArray();
      const allPolicies = await db.policies.toArray();
      setUsers(allUsers);
      setPolicies(allPolicies);
  };

  useEffect(() => {
    fetchData();
  }, [section]);

  const fetchPolicyTransactions = async (policy: Policy) => {
    if (!policy.id) return;
    const txs = await db.transactions.where('referenceId').equals(policy.id.toString()).toArray();
    setPolicyTransactions(txs);
    setSelectedPolicy(policy);
  };

  const handleExportPolicies = () => {
    const data = policies.map(p => ({
        ID: p.id,
        Policy_Number: p.policyNumber,
        Type: p.type,
        Premium: p.premium,
        Status: p.status,
        Created_At: p.createdAt,
        Provider: p.providerId,
        Vehicle: p.coverageDetails?.vehicle?.brand || 'N/A'
    }));
    downloadCSV(data, 'SurePath_Active_Nodes');
  };

  const handleImportPolicies = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
        const text = event.target?.result as string;
        const rows = text.split('\n').slice(1);
        for (const row of rows) {
            const cols = row.split(',');
            if (cols.length >= 4) {
                // Mock import logic
                console.log("Importing policy row:", row);
            }
        }
        await fetchData();
        setLoading(false);
        alert("Batch registry synchronization complete.");
    };
    reader.readAsText(file);
  };

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userForm.name || !userForm.email || !userForm.password) return;
    setLoading(true);
    try {
        const { hash, salt } = await hashPassword(userForm.password);
        const newNodeId = `SP-${userForm.role === UserRole.CUSTOMER ? 'NODE' : 'ADMIN'}-${Math.floor(1000 + Math.random() * 9000)}`;
        const newUser: DBUser = {
            name: userForm.name, email: userForm.email, phone: userForm.phone,
            passwordHash: hash, salt: salt, role: userForm.role, nodeId: newNodeId,
            verified: true, trustScore: 100, memberSince: new Date().toISOString()
        };
        await db.users.add(newUser);
        setIsAddingUser(false);
        fetchData();
    } catch (err) {
        alert("Registry fault.");
    } finally {
        setLoading(false);
    }
  };

  if (section === 'transactions') {
     return (
        <div className="space-y-6">
           <div className="flex justify-between items-center px-4">
              <h3 className="text-sm font-black uppercase tracking-widest text-primary-500">Node Lifecycle Traffic</h3>
              <div className="flex gap-3">
