      "photoFlags": [
        { "id": "id_foto", "status": "OK" | "FRAUD_DETECTED" | "POOR_QUALITY" | "NOT_MATCHING" | "DARK_PHOTO", "reason": "Reason (In Indonesian)" }
      ],
      "auditVerdict": "CLEAN" | "REVIEW_REQUIRED" | "REJECTED",
