  const loadDraft = () => {
    const draft = localStorage.getItem(DRAFT_KEY);
    if (draft) {
      const data = JSON.parse(draft);
      setClaimType(data.claimType);
      setStep(data.step);
      setClaimResult(data.claimResult);
      setHealthResult(data.healthResult);
      setPhotoBase64(data.photoBase64);
